"""Review eight sites; preserve only exact individual decisions from the received export."""
from pathlib import Path
import json,hashlib,html
P=Path(__file__).resolve().parent
read=lambda f:json.loads((P/f).read_text())
esc=html.escape
d=read('borrador.json');selection=read('seleccion-editorial.json');assets={a['id']:a for a in read('imagenes/manifiesto.json')};ledger=read('decisiones-usuario.json');prior={x['id']:x for x in ledger['decisions']};components=[];blocks=[];historical_values={x['id']:x['value'] for x in read('historial/revision-116-componentes-3fab25.json')['components']}
def component(ident,scope,value,image=None):
 fingerprint=hashlib.sha256(json.dumps(value,ensure_ascii=False,sort_keys=True).encode()).hexdigest()
 before=prior.get(ident);matching=before and before['component_sha256']==fingerprint and before['scope']==scope
 image_binding=None
 if image and before and before['decision']=='aprobado' and before['scope']==scope:
  previous=historical_values.get(ident,{})
  if previous.get('original',{}).get('sha256')==value['original']['sha256']:
   matching=True; image_binding={'original_sha256':value['original']['sha256'],'use':scope,'source_component_sha256':before['component_sha256']}
 decision=before['decision'] if matching else None
 components.append(dict(id=ident,scope=scope,sha256=fingerprint,value=value,decision=decision,approval_source_revision=before['source_revision'] if matching and decision=='aprobado' else None,approval_image_binding=image_binding))
 body=''
 if image:
  body=f'<img loading="lazy" src="{image}" alt="{esc(value["alt"]["es"])}"><p class="credit">{esc(value["credit"])} · <a href="{value["original"]["file"]}">Original</a> · <a href="{value["source_page"]}">Procedencia</a> · <a href="{value["license_url"]}">Licencia</a>. Permiso comercial/adaptación comprobado por el agente; no requiere una casilla adicional.</p><p>{esc(value["recency_warning"])}</p>'
 else:
  for lang,text in value.items():
   body+=f'<details {"open" if lang=="es" else ""}><summary>{esc(lang)}</summary>'+''.join(f'<p>{esc(str(x))}</p>' for x in (text if isinstance(text,list) else [text]))+'</details>'
 status='<p class="approved"><strong>Ya aprobado por ti para este componente exacto.</strong> No necesitas aprobarlo de nuevo. La ilustración final y publicación siguen pendientes.</p>' if decision=='aprobado' else ('<p>Contenido modificado; tu decisión anterior permanece en el historial y no se aplica a esta versión.</p>' if before and not matching else '<p>Pendiente de tu revisión.</p>')
 if ident=='CTG-03':status+='<p>Tu corrección: buscar una mejor foto de Getsemaní. Propongo otra toma de casas y calle sin personas dominantes; sus textos aprobados se conservan.</p>'
 control='<p>Decisión registrada: aprobado.</p>' if decision=='aprobado' else '<label>Decisión de este componente<select><option value="pendiente">Pendiente</option><option value="aprobado">Apruebo solo este componente para su uso indicado</option><option value="corregir">Solicito cambios</option></select></label>'
 blocks.append(f'<article data-id="{ident}" data-hash="{fingerprint}" data-recorded="{decision or "pendiente"}"><h3>{esc(ident)} · {esc(scope)}</h3>{body}{status}{control}<label>Comentario<textarea rows="2">{esc(before["comment"] if before and matching else "")}</textarea></label></article>')
blocks.append('<header><p>Borrador privado · Lugar1 · sin publicación</p><h1>Cartagena: ocho atractivos principales</h1><p>Conservé tus aprobaciones. Revisa la selección y los componentes nuevos o corregidos; los que dicen «Ya aprobado» siguen válidos. Actividades e investigación adicional aparecen aparte.</p><p>La portada1 ya fue elegida. Su ilustración está autorizada condicionalmente, pero se aplaza mientras corregimos esta selección. Todavía no se ha generado ninguna imagen con IA.</p><nav><a href="#portada">Portada</a><a href="#historia">Historia</a><a href="#atractivos">8 atractivos</a><a href="#actividades">Actividades</a><a href="#historial">Historial</a></nav></header>')
blocks.append('<section id="portada"><h2>Portada elegida · opción1</h2><p>Panorama desde La Popa. No se repite en la ficha del convento: allí propongo su claustro.</p>')
component('CTG-01','Opción 1 · original para posible portada · panorama Cartagena desde La Popa (2008); muestra bahía/ciudad, cruz dominante; sin recorte móvil ni escritorio',assets['la-popa-2008'],assets['la-popa-2008']['derivatives'][0]['file'])
for lang,t in d['destination']['translations'].items():component('CTG-PORTADA-TEXTO-'+lang,'Título, presentación y descripción de buscadores · '+lang,{lang:[t['display_name'],t['eyebrow'],t['headline'],t['intro'],t['meta_description']]})
blocks.append('</section><section id="historia"><h2>Historia · aprobada en tres idiomas</h2>')
for lang,text in d['destination']['history'].items():component('CTG-HISTORIA-'+lang,'Texto de historia · '+lang,{lang:text})
blocks.append('</section><section id="atractivos"><h2>Selección principal · máximo ocho</h2><p>Ocho fichas con referencia local real y derechos comprobados: patrimonio, barrios, mar, paisaje y vida local.</p><div class="cards">')
by_slug={p['slug']:p for p in d['places']}
for row in selection['selection']:
 place=by_slug[row['slug']];name=place['translations']['es']['name'];a=assets[row['photo_asset']]
 blocks.append(f'<div class="attraction-card" data-site="{place["slug"]}"><h2>{row["order"]}. {esc(name)}</h2><p>{esc(row["reason"])}</p>')
 ident={'san-felipe':'CTG-02','getsemani':'CTG-03','museo-historico':'CTG-04'}.get(place['slug'],'CTG-FOTO-'+place['slug'])
 component(ident,'Foto de la ficha «'+name+'»',a,place['image']['file'])
 for lang,t in place['translations'].items():component('CTG-LUGAR-'+place['slug']+'-'+lang,'Nombre y descripción de «'+name+'» · '+lang,{lang:[t['name'],t['description']]})
 blocks.append('</div>')
blocks.append('</div></section><section id="actividades"><h2>Actividades · separadas de los ocho lugares</h2><p>No implican alianza, disponibilidad o reserva con el portal. Fotos específicas pendientes de permiso y validación; no se sustituyen por monumentos.</p>')
for exp in d['experiences']:
 blocks.append(f'<details><summary>{esc(exp["id"])} · {esc(exp["experience_class"])}</summary><p>{esc(exp["blocking_reason"])}</p><p>Operador: {esc(str(exp.get("operator")))} · <a href="{esc(exp.get("operator_url", ""))}">Fuente</a></p><p>Referencias investigadas: {esc(str(exp.get("visual_candidates",[])))}</p>')
 for lang,t in exp['translations'].items():component('CTG-EXP-'+exp['id']+'-'+lang,'Texto borrador privado de experiencia «'+exp['id']+'» · '+lang+' · NO habilita oferta, reserva ni publicación',{lang:t})
 blocks.append('</details>')
blocks.append('</section><details><summary>Información práctica y directorio gratuito</summary>')
for lang,t in d['practical'].items():component('CTG-PRACTICA-'+lang,'Información práctica · '+lang,{lang:t})
for business in read('directorio.json'):component('CTG-DIR-'+business['id'],'Ficha gratuita de '+business['name'],{'es':[business['name'],business['category'],business['source_url'],business['notes']]})
blocks.append('</details>')
active={c['id'] for c in components if c['decision']=='aprobado'};approved=[x for x in ledger['decisions'] if x['decision']=='aprobado'];inactive=[x for x in approved if x['id'] not in active]
blocks.append(f'<details id="historial"><summary>Investigación e historial · {len(approved)} aprobaciones históricas, {len(active)} intactas en revisión actual</summary><p>Los19 sitios investigados se conservan. Torre del Reloj y Portal de los Dulces se agrupan dentro del centro. Los secundarios no se borraron. Aprobaciones de textos retirados o modificados permanecen en su versión original; no se transfieren.</p><ul>'+''.join('<li>'+esc(x['id'])+' · aprobación histórica conservada; fuera de selección o versión modificada.</li>' for x in inactive)+'</ul><p><a href="historial/revision-116-componentes-3fab25.json">Contenido original de116 componentes</a> · <a href="historial/decision-usuario-original-3fab25.json">Exportación original</a> · <a href="borrador.json">Inventario</a></p></details>')
revision=hashlib.sha256(json.dumps(components,ensure_ascii=False,sort_keys=True).encode()).hexdigest()
bindings=[dict(id=c['id'],scope=c['scope'],component_sha256=c['sha256'],approval_source_revision=c['approval_source_revision'],original_use_binding=c.get('approval_image_binding')) for c in components if c['decision']=='aprobado']
(P/'aprobaciones-vigentes.json').write_text(json.dumps(dict(current_revision=revision,historical_approved_total=len(approved),active_unchanged_total=len(bindings),active_approvals=bindings,historical_outside_or_changed=[x['id'] for x in inactive],conditional_generation_authorization=ledger['conditional_generation_authorization'],final_art_approved=False,publication_authorized=False),ensure_ascii=False,indent=2)+'\n')
(P/'revision-componentes.json').write_text(json.dumps(dict(destination='cartagena',revision=revision,publication_approved=False,selection_approved=False,historical_approvals=len(approved),active_unchanged_approvals=len(active),components=components),ensure_ascii=False,indent=2)+'\n')
script='''const revision=REVISION;const components=COMPONENTS;const key='revision-cartagena-'+revision;const articles=[...document.querySelectorAll('article[data-id]')];function snapshot(){return {destino:'cartagena',revision,portada_seleccionada:'1',alcance:'Decisiones individuales; no autoriza publicación',elementos:articles.map(a=>{let c=components.find(c=>c.id===a.dataset.id);return {id:c.id,alcance:c.id+' · '+c.scope,component_sha256:c.sha256,decision:a.querySelector('select')?.value||a.dataset.recorded,comentario:a.querySelector('textarea').value}})}}let saved;try{saved=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(saved)for(const a of articles){let x=saved.elementos.find(x=>x.id===a.dataset.id&&x.component_sha256===a.dataset.hash);if(x&&a.querySelector('select')){a.querySelector('select').value=x.decision;a.querySelector('textarea').value=x.comentario}}document.addEventListener('input',()=>{try{localStorage.setItem(key,JSON.stringify(snapshot()))}catch{}});document.querySelector('#exportar').onclick=()=>{const output=JSON.stringify(snapshot(),null,2);document.querySelector('#resultado').value=output;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([output],{type:'application/json'}));a.download='revision-cartagena.json';a.click();URL.revokeObjectURL(a.href)};'''.replace('REVISION',json.dumps(revision)).replace('COMPONENTS',json.dumps(components,ensure_ascii=False).replace('</','<\\/'))
style='''body{font:17px/1.6 system-ui;background:#fffaf2;color:#172b42;margin:0;overflow-wrap:anywhere}main{max-width:1200px;margin:auto;padding:24px}section,article,.attraction-card{margin:20px 0;padding:20px;border:1px solid #f2c77e;border-radius:12px;background:#fff8ed}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.attraction-card{min-width:0;margin:0;padding:16px}.attraction-card article{padding:12px}img{width:100%;height:auto}a{color:#a83b22}label{display:block;margin:12px 0}select,textarea,button{box-sizing:border-box;font:inherit;max-width:100%;padding:10px}select,textarea{width:100%}nav{display:flex;gap:20px;flex-wrap:wrap}.approved{border-left:4px solid #315e9d;padding-left:12px}.credit{font-size:14px}summary{cursor:pointer}h1{font-size:clamp(2rem,5vw,3rem)}@media(max-width:800px){.cards{grid-template-columns:1fr}main{padding:16px}.attraction-card article{padding:10px}}'''
ending='<section><h2>Enviar decisiones nuevas</h2><p>Exporta y comparte en el chat. Las aprobaciones intactas ya están registradas; revisa lo nuevo o corregido. No equivale a aprobar la selección completa, ilustración final o publicación.</p><button id="exportar">Exportar revisión</button><textarea id="resultado" rows="6" readonly aria-label="Decisiones para copiar"></textarea><p><a href="fuentes.json">Fuentes</a> · <a href="decisiones-usuario.json">Decisiones registradas</a> · <a href="seleccion-editorial.json">Criterio</a></p></section>'
(P/'preview.html').write_text('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Cartagena · ocho atractivos</title><style>'+style+'</style><main>'+''.join(blocks)+ending+'</main><script>'+script+'</script></html>')
print('Review8:',len(components),'components;',len(approved),'historical approvals;',len(active),'intact active approvals; no generated illustration.')
